var a=11;var s=`011-tasting-and-sensory-evaluation`;var i=`001`;var n={en:`Tasting and Sensory Evaluation`,ua:`Дегустація та органолептичне оцінювання`};var o={short:`Sensory evaluation describes food through appearance, aroma, taste, texture, and sound. Structured tasting makes it easier to diagnose quality problems and compare recipes, but it cannot establish microbiological safety.`,sections:[{title:`Core idea`,text:`Our senses integrate multiple signals: smell contributes strongly to flavor, the tongue detects basic tastes, and texture includes firmness, creaminess, crispness and other mouthfeel properties. Temperature can also change perceived sweetness, aroma and fat texture.`},{title:`Scientific / practical principles`,text:`A repeatable evaluation isolates attributes rather than saying only “good” or “bad.” Ask whether salt is balanced, acid is sufficient, aroma is pleasant, and the target texture matches the dish. Different tasters and contexts can produce different judgments.`},{title:`How to apply it`,text:`Taste safe food in small samples at an appropriate serving temperature. Compare one variable at a time, use descriptive language, and record observations before adjusting the recipe. For dangerous or suspected spoiled foods, do not taste.`},{title:`Practical example`,text:`When testing two tomato sauces, a cook can rate acidity, sweetness, salt, herb aroma and thickness separately. The comparison then shows what to adjust, such as reducing one sauce or adding a small amount of salt.`},{title:`Common mistakes and limitations`,text:`Personal preference is not the same as a measured defect, and blind tasting is useful for reducing expectation bias. Never use smell, appearance or taste as a substitute for safe handling and temperature controls.`}]};var r={short:`Органолептичне оцінювання описує їжу за виглядом, ароматом, смаком, текстурою та звуком. Структурована дегустація допомагає порівнювати рецепти й виявляти проблеми якості, але не доводить мікробіологічної безпечності.`,sections:[{title:`Суть`,text:`Людина поєднує кілька сигналів: нюх сильно впливає на загальне відчуття смаку, язик розрізняє основні смаки, а текстура охоплює твердість, кремовість, хрусткість та інші відчуття в роті. Температура також змінює сприйняття аромату й жиру.`},{title:`Наукові та практичні принципи`,text:`Відтворюване оцінювання розділяє ознаки замість загальної оцінки «смачно/несмачно». Перевіряйте баланс солі, кислотність, аромат та відповідність бажаній текстурі. Різні люди й умови дегустації можуть змінювати оцінки.`},{title:`Як застосовувати`,text:`Куштуйте тільки безпечну їжу невеликими порціями за відповідної температури подачі. Порівнюйте одну змінну за раз, використовуйте точні описи й записуйте спостереження перед зміною рецепта. Підозрілі або зіпсовані продукти не куштуйте.`},{title:`Практичний приклад`,text:`Порівнюючи два томатні соуси, можна окремо оцінити кислотність, солодкість, сіль, аромат трав та густину. Тоді буде зрозуміло, що варто змінити: додатково уварити соус або трохи досолити.`},{title:`Поширені помилки й обмеження`,text:`Особисті вподобання не завжди означають дефект, а сліпа дегустація може зменшити вплив очікувань. Ніколи не використовуйте запах чи смак замість належного зберігання та температурного контролю.`}]};var l=[57,58,69,286];var c=`References / Джерела`;var d=[`https://www.ciachef.edu/online-resources/`,`https://www.fda.gov/food/buy-store-serve-safe-food/safe-food-handling`];var u={id:11,slug:s,group:`001`,title:n,en:o,ua:r,related:l,referenceTitle:c,references:d};export{u as default,o as en,i as group,a as id,c as referenceTitle,d as references,l as related,s as slug,n as title,r as ua};